  }
  console.log(`Wiederherstellung aus ${name} abgeschlossen, Nachkontrolle OK (${Object.keys(manifest.dateien).length} Dateien).`);
  if (netz) console.log(`Stand davor gesichert als: .data-sicherungen/${netz}`);
