  else {
    console.log("Aufruf: node scripts/demo-sicherung.mjs sichern [name] | liste | pruefen <name> | wiederherstellen <name>");
    process.exit(1);
  }
} catch (e) {
  console.error("Fehler:", e?.message || e);
  process.exit(1);
}

